<template><div class="page-container fsr-page"><div class="page-head"><div><h2>长势对比库</h2><p>基于多源农情记录形成作物长势、产量趋势与田管措施对比。</p></div><el-button type="primary" @click="load">刷新对比</el-button></div><div class="stat-grid"><div class="stat-card blue"><span>长势对比记录</span><strong>{{ rows.length }}</strong><small>条</small></div><div class="stat-card orange"><span>待研判区域</span><strong>{{ pending }}</strong><small>个</small></div><div class="stat-card green"><span>长势良好率</span><strong>{{ goodRate }}%</strong><small>记录占比</small></div><div class="stat-card red"><span>减产风险记录</span><strong>{{ yieldRisk }}</strong><small>条</small></div></div><div class="panel"><div class="panel-title">长势对比记录列表</div><el-table :data="records" stripe border><el-table-column type="index" label="序号" width="60"/><el-table-column prop="recordTime" label="记录时间" width="120"/><el-table-column prop="region" label="监测区域" min-width="150"/><el-table-column prop="sourceName" label="数据来源" width="135"/><el-table-column prop="crop" label="在地作物" width="100"/><el-table-column prop="variety" label="种植品种" width="130"/><el-table-column prop="growth" label="苗情长势" width="100"/><el-table-column prop="yieldTrend" label="产量趋势" width="100"/><el-table-column prop="measure" label="田管措施" min-width="180" show-overflow-tooltip/><el-table-column prop="suggestion" label="区域建议" min-width="180" show-overflow-tooltip/></el-table></div><div class="analysis-grid"><div class="panel chart-panel"><div class="panel-title">在地作物对比</div><BaseChart :option="cropOption" height="260px"/></div><div class="panel chart-panel"><div class="panel-title">数据来源分布</div><BaseChart :option="sourceOption" height="260px"/></div><div class="panel chart-panel"><div class="panel-title">苗情长势分布</div><BaseChart :option="growthOption" height="260px"/></div><div class="panel chart-panel"><div class="panel-title">产量趋势分布</div><BaseChart :option="yieldOption" height="260px"/></div></div></div></template>
<script setup>
import { computed, onMounted, ref } from 'vue'; import BaseChart from '@/components/charts/BaseChart.vue'; import { fetchEvents } from '@/api/fsr'; import { useUserStore } from '@/stores/user'
const userStore=useUserStore();const rows=ref([]);const sourceMap={remote:'遥感卫片',fence:'无人机航拍',platform:'市级反馈',grid:'县级反馈',snapshot:'苗情监测报告'};const cropMap={baomai:'小麦',piaohuang:'玉米',feilianghua:'水稻',zhangshi:'水稻'};const records=computed(()=>rows.value.map(e=>{const crop=cropMap[e.type]||'小麦';const growth=e.type==='zhangshi'?'偏弱':e.risk==='high'?'需关注':'良好';return {recordTime:e.foundTime,region:e.regionName,sourceName:sourceMap[e.source]||'苗情监测报告',crop,variety:crop==='水稻'?'优质稻':'皖麦系列',growth,yieldTrend:growth==='良好'?'稳中有增':growth==='偏弱'?'下降风险':'基本稳定',measure:e.checkReport?.desc||'加强田间巡查与水肥管理',suggestion:growth==='良好'?'保持常态化监测':'建议属地开展现场核查并落实田管措施'}}));const count=key=>{const m={};records.value.forEach(x=>{m[x[key]]=(m[x[key]]||0)+1});return Object.entries(m).map(([name,value])=>({name,value}))};const pie=key=>computed(()=>({tooltip:{trigger:'item'},legend:{bottom:0},series:[{type:'pie',radius:['38%','68%'],data:count(key),label:{formatter:'{b} {d}%'}}]}));const pending=computed(()=>records.value.filter(x=>x.growth!=='良好').length);const goodRate=computed(()=>records.value.length?((records.value.filter(x=>x.growth==='良好').length/records.value.length)*100).toFixed(1):'0.0');const yieldRisk=computed(()=>records.value.filter(x=>x.yieldTrend==='下降风险').length);const cropOption=pie('crop');const sourceOption=pie('sourceName');const growthOption=pie('growth');const yieldOption=pie('yieldTrend');const load=async()=>{rows.value=await fetchEvents(userStore.role,{})};onMounted(load)
</script><style scoped lang="scss">.fsr-page{overflow:auto}.page-head{display:flex;justify-content:space-between;margin-bottom:14px}.page-head h2{margin:4px 0;font-size:22px}.page-head p{margin:0;color:var(--ah-text-secondary);font-size:13px}.panel-title{margin-bottom:12px;font-weight:700}.stat-grid,.analysis-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:12px}.analysis-grid{grid-template-columns:1fr 1fr}.stat-card{padding:15px;background:#fff;border:1px solid var(--ah-border);border-top:3px solid var(--ah-primary);border-radius:8px}.stat-card span,.stat-card small{display:block;color:var(--ah-text-secondary);font-size:12px}.stat-card strong{display:inline-block;margin:7px 5px 2px 0;font-size:25px}.orange{border-top-color:#e6a23c}.green{border-top-color:#67c23a}.red{border-top-color:#f56c6c}@media(max-width:700px){.stat-grid,.analysis-grid{grid-template-columns:1fr 1fr}}</style>